def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Uses patience sorting with binary search, O(n log n).
    """
    import bisect
    if not nums:
        return 0
    tails = []
    for x in nums:
        # find insertion point
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

