def solve(grid):
    """Return the number of islands in a binary grid.
    Handles empty grid, empty rows, and jagged rows.
    """
    if not grid:
        return 0
    visited = set()
    rows = len(grid)
    def neighbors(r, c):
        for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows:
                if 0 <= nc < len(grid[nr]):
                    yield nr, nc
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            visited.add((i, j))
            for ni, nj in neighbors(i, j):
                if (ni, nj) not in visited and grid[ni][nj] == 1:
                    stack.append((ni, nj))
    islands = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and (i, j) not in visited:
                islands += 1
                dfs(i, j)
    return islands

